74:     /** Remote operations used by the domain pages. */
75:     public interface Backend {
76:         /** Loads the domains of the signed in account. */
77:         JSONObject fetchAllDomains() throws Exception;
78: 
79:         /** Searches the available paid domain suggestions for a query. */
80:         JSONArray searchForDomains(String query) throws Exception;
81: 
82:         /** Creates the purchase cart for a mode and a domain. */
83:         JSONObject createCart(String mode, String domain) throws Exception;
84: 
85:         /**
86:          * Richer all-domains call. The default keeps existing backends working by reusing
87:          * {@link #fetchAllDomains()}.
88:          */
89:         default JSONObject fetchAllDomainsPage() throws Exception {
90:             return fetchAllDomains();
91:         }
92: 
93:         /**
94:          * Richer suggestions call returning the response envelope so that a mismatching response can
95:          * be detected. The default wraps {@link #searchForDomains(String)} into the same envelope.
96:          */
97:         default JSONObject searchDomainSuggestions(String query) throws Exception {
98:             JSONArray suggestions = searchForDomains(query);
99:             JSONObject envelope = Json.object();
100:             Json.put(envelope, "query", query);
101:             Json.put(envelope, "suggestions", suggestions == null ? Json.array() : suggestions);
102:             return envelope;
103:         }
104: 
105:         /**
106:          * Richer cart call carrying the product identifier, the privacy capability and the site a
107:          * domain should be attached to. The default keeps existing backends working by reusing
108:          * {@link #createCart(String, String)}.
109:          */
110:         default JSONObject createCartForProposal(JSONObject request) throws Exception {
111:             String mode = request == null ? "" : request.optString("mode", "");
112:             String domain = request == null ? "" : request.optString("domain", "");
113:             JSONObject response = createCart(mode, domain);
114:             return response == null ? null : response;
115:         }
