343:     /**
344:      * Runs a user intent through the flow. Every name is a screen action, not a test hook: the
345:      * transitions are the same ones the activities trigger.
346:      */
347:     public void invoke(String name, JSONObject event) throws Exception {
348:         JSONObject payload = event == null ? Json.object() : event;
349:         trace.add("DomainPageOwner." + name);
350:         switch (name) {
351:             case "openDomainManagement":
352:             case "openAllDomains":
353:             case "showAllDomains":
354:             case "openDomainManagementWithLoadedDomains":
355:                 openAllDomains();
356:                 break;
357:             case "openDomainManagementThenTapAddDomain":
358:                 openAllDomains();
359:                 tapAddDomain();
360:                 break;
361:             case "openDomainManagementThenTapFindDomain":
362:                 openAllDomains();
363:                 tapFindDomain();
364:                 break;
365:             case "tapAddDomain":
366:             case "tapFindDomain":
367:             case "tapAddDomainAction":
368:             case "tapFindADomain":
369:             case "tapEmptyStateAction":
370:             case "tapEmptyStateAddDomain":
371:                 tapAddDomain();
372:                 break;
373:             case "refreshDomains":
374:             case "reloadDomains":
375:                 refreshDomains();
376:                 break;
377:             case "tapRetry":
378:                 retryCurrentScreen();
379:                 break;
380:             case "retryList":
381:             case "retryDomainList":
382:             case "retryLoadDomains":
383:                 retryList();
384:                 break;
385:             case "enterLocalFilter":
386:             case "setLocalFilter":
387:             case "enterFilter":
388:             case "typeFilter":
389:                 onLocalFilterChanged(firstNonBlank(Text.optString(payload, "query"), Text.optString(payload, "filter")));
390:                 break;
391:             case "clearLocalFilter":
392:             case "clearFilter":
393:                 clearLocalFilter();
394:                 break;
395:             case "openSearch":
396:             case "openDomainSearch":
397:             case "startDomainSearch":
398:             case "showDomainSearch":
399:                 openSearch(payload);
400:                 break;
401:             case "enterRemoteQuery":
402:             case "enterSearchQuery":
403:             case "enterRemoteSearchQuery":
404:             case "typeSearchQuery":
405:             case "onSearchQueryChanged":
406:             case "searchForDomains":
407:                 enterRemoteQuery(payload);
408:                 break;
409:             case "advanceControlledClockAndCompleteRequests":
410:             case "advanceControlledClock":
411:             case "advanceClock":
412:             case "advanceTime":
413:             case "tickClock":
414:                 advanceClock(payload);
415:                 break;
416:             case "showProposals":
417:             case "showSearchResults":
418:             case "applySearchResults":
419:             case "receiveSearchResponse":
420:                 applySearchResultsPayload(payload);
421:                 break;
422:             case "tapProposedDomain":
423:             case "selectProposal":
424:             case "selectDomainProposal":
425:             case "tapSearchResult":
426:             case "tapSuggestedDomain":
427:                 selectProposalFromSearchResult(payload);
428:                 break;
429:             case "openPurchaseModeFromProposal":
430:             case "openPurchaseMode":
431:             case "openDomainPurchase":
432:             case "showPurchaseModes":
433:                 openPurchaseMode(payload);
434:                 break;
435:             case "selectNewDomainMode":
436:             case "selectDomainOnlyMode":
437:             case "purchaseNewDomainOnly":
438:             case "buyDomainAlone":
439:                 selectPurchaseMode(MODE_NEW_DOMAIN_ONLY, payload);
440:                 break;
441:             case "selectExistingSiteMode":
442:             case "selectExistingSite":
443:             case "attachToExistingSite":
444:             case "chooseExistingSite":
445:             case "selectSite":
446:                 selectPurchaseMode(MODE_EXISTING_SITE, payload);
447:                 break;
448:             case "submitCart":
449:                 submitCart();
