455:             case "acknowledgeCartErrorThenRetryNewDomain":
456:             case "acknowledgeCartErrorThenRetry":
457:             case "retryCartAfterAcknowledgingError":
458:                 acknowledgeCartError();
459:                 submitCart();
460:                 break;
461:             case "retryCart":
462:             case "submitCartAgain":
463:                 retryCart();
