473:                 onCheckoutResult(payload);
474:                 break;
475:             case "openDetails":
476:             case "openDomainDetails":
477:             case "tapDomainDetails":
478:                 openDetails(payload);
479:                 break;
480:             case "requestDetailsNavigation":
481:             case "shouldOverrideUrlLoading":
482:             case "navigateDetails":
483:                 requestDetailsNavigation(payload);
484:                 break;
485:             case "closeDetails":
486:             case "closeSearch":
487:             case "closePurchaseScreen":
488:             case "cancelPurchaseMode":
