518:     /** Production entry point used by the all-domains screen. */
519:     public void refreshDomains() {
520:         final Backend currentBackend = backend;
521:         if (currentBackend == null) {
522:             applyListError("no domain backend is available");
523:             return;
524:         }
525:         final int requestId = ++listRequestCount;
526:         setListState(LIST_LOADING);
527:         listError = "";
528:         trace.add("DomainPageOwner.loadDomains()");
529:         emit("fetchAllDomains", "requestIndex", requestId, "count", listRequestCount,
530:                 "retainedQuery", filterQuery);
531:         scheduler.executeOnWorker(new Runnable() {
532:             @Override public void run() {
533:                 JSONObject response;
534:                 try {
535:                     response = currentBackend.fetchAllDomainsPage();
536:                 } catch (Exception error) {
537:                     response = errorResponse(error);
538:                 }
539:                 final JSONObject payload = response;
540:                 scheduler.post(new Runnable() {
541:                     @Override public void run() {
542:                         applyListResponse(requestId, payload);
543:                     }
544:                 });
545:             }
546:         });
547:     }
