571:     /** Retry repeats whichever operation produced the visible error. */
572:     public void retryCurrentScreen() {
573:         if (listState == LIST_ERROR && !detailsScreenOpen && !checkoutScreenOpen) {
574:             retryList();
575:             return;
576:         }
577:         if (searchState == SEARCH_ERROR) {
578:             retrySearch();
579:             return;
580:         }
581:         if (cartState == CART_ERROR) {
582:             // The failure is acknowledged first, which keeps the selected proposal for the retry.
583:             acknowledgeCartError();
584:             submitCart();
585:             return;
586:         }
587:         if (checkoutState == CHECKOUT_ERROR) {
588:             // The checkout could not be completed; the cart is still there to continue from.
589:             retryCheckout();
590:             return;
591:         }
592:         emit("retryIgnored", "listState", listState, "searchState", searchState, "cartState", cartState);
593:     }
