595:     private void applyListResponse(int requestId, JSONObject response) {
596:         if (requestId != listRequestCount) {
597:             // A newer all-domains request is in flight; the stale response is dropped.
598:             emit("staleListResponseIgnored", "requestIndex", requestId);
599:             return;
600:         }
601:         listRequestLog.add(describeListResponse(response));
602:         trim(listRequestLog);
603:         if (isErrorResponse(response)) {
604:             applyListError(Text.isBlank(errorMessage(response))
605:                     ? "the account domains could not be loaded" : errorMessage(response));
606:             return;
607:         }
608:         JSONArray domains = domainsOf(response);
609:         if (domains == null) {
610:             if (isExplicitlyEmpty(response)) {
611:                 replaceAccountDomains(Json.array());
612:                 setListState(LIST_EMPTY);
613:                 filterAccountDomains(filterQuery);
614:                 notifyObservers();
615:                 return;
616:             }
617:             applyListError("the account domains response could not be read");
618:             return;
619:         }
620:         replaceAccountDomains(domains);
621:         setListState(accountDomains.isEmpty() ? LIST_EMPTY : LIST_COMPLETE);
622:         filterAccountDomains(filterQuery);
623:         notifyObservers();
624:     }
625: 
626:     private void applyListError(String message) {
627:         listError = Text.orEmpty(message);
628:         // A failed load owns no rows at all, so no stale domain can be shown or filtered.
629:         accountDomains.clear();
630:         visibleDomains.clear();
631:         setListState(LIST_ERROR);
632:         emit("allDomainsLoadFailed", "message", listError, "retryable", true);
633:         notifyObservers();
634:     }
635: 
636:     private void replaceAccountDomains(JSONArray domains) {
637:         accountDomains.clear();
638:         for (int index = 0; index < domains.length(); index++) {
639:             JSONObject entry = domains.optJSONObject(index);
640:             if (entry == null) {
641:                 String value = domains.optString(index, "");
642:                 if (Text.isBlank(value)) {
643:                     continue;
644:                 }
645:                 accountDomains.add(new DomainRow(value, "", "", "", ""));
646:                 continue;
647:             }
648:             accountDomains.add(DomainRow.fromJson(entry));
649:         }
650:     }
