658:     /** Filters the loaded list; the account's stored domains are never mutated. */
659:     public void onLocalFilterChanged(String query) {
660:         trace.add("DomainPageOwner.applyLocalFilter()");
661:         filterQuery = Text.orEmpty(query);
662:         filterAccountDomains(filterQuery);
663:         emit("filterLoadedDomains",
