689:     /**
690:      * Applies the local filter to the account's domains. Filtering only ever changes the visible
691:      * rows of a loaded list: the stored collection and the loaded state itself are left alone.
692:      */
693:     private void filterAccountDomains(String query) {
694:         if (!isListUsable()) {
695:             // Nothing is loaded, so there is no list to filter and nothing to show.
696:             visibleDomains.clear();
697:             return;
698:         }
699:         String normalized = Text.normalizeQuery(query);
700:         visibleDomains.clear();
701:         for (DomainRow row : accountDomains) {
702:             if (row.matches(normalized)) {
703:                 visibleDomains.add(row);
704:             }
705:         }
706:         if (accountDomains.isEmpty()) {
707:             // An account without domains stays empty; it never becomes a filtered list.
708:             setListState(LIST_EMPTY);
709:             return;
710:         }
711:         setListState(normalized.isEmpty() ? LIST_COMPLETE : LIST_FILTERED);
712:     }
