726:     /** Opens the new-domain search flow with an empty query and no proposals. */
727:     public void openSearch(JSONObject payload) {
728:         registerResponseDeadlines(payload);
729:         Long start = timestampOf(payload);
730:         if (start != null) {
731:             useControlledClock(start);
732:         }
733:         cancelPendingDispatch();
734:         screen = SCREEN_DOMAIN_SEARCH;
