754:     /** Production entry point used by the search field. */
755:     public void onSearchQueryChanged(String rawQuery) {
756:         onSearchQueryChanged(rawQuery, null);
757:     }
758: 
759:     /**
760:      * Accepts a typed query. When the caller knows the moment the query was typed (a driver with a
761:      * controlled clock), that moment is honoured so a debounce deadline is exact; otherwise the
762:      * page clock decides.
763:      */
764:     private void onSearchQueryChanged(String rawQuery, Long typedAtMillis) {
765:         String normalized = Text.normalizeQuery(rawQuery);
766:         if (Text.isBlank(normalized)) {
767:             onBlankSearchQuery();
768:             return;
769:         }
770:         if (typedAtMillis != null) {
771:             useControlledClock(typedAtMillis);
772:             advanceControlledClockTo(typedAtMillis);
773:         }
774:         searchQuery = normalized;
775:         searchError = "";
776:         queryGeneration++;
777:         cancelPendingDispatch();
778:         proposals.clear();
779:         setSearchState(SEARCH_DEBOUNCING);
780:         final String query = normalized;
781:         pendingQuery = query;
782:         pendingDueAt = scheduler.nowMillis() + SEARCH_DEBOUNCE_MS;
783:         pendingDispatch = scheduler.postDelayed(new Runnable() {
784:             @Override public void run() {
785:                 dispatchSearch(query);
786:             }
787:         }, SEARCH_DEBOUNCE_MS);
788:         emit("searchQueryChanged",
789:                 "query", query,
790:                 "normalizedQuery", query,
791:                 "debounceMs", SEARCH_DEBOUNCE_MS,
792:                 "dueAt", pendingDueAt);
793:         notifyObservers();
794:     }
795: 
796:     /** Blank input never reaches the backend and keeps the results of the last real query. */
797:     private void onBlankSearchQuery() {
798:         boolean cancelledPending = cancelPendingDispatch();
799:         boolean searching = searchState == SEARCH_LOADING || searchState == SEARCH_DEBOUNCING;
800:         if (searching && proposals.isEmpty()) {
801:             // Nothing is in flight any more, so no response may claim the visible state.
802:             queryGeneration++;
803:             searchError = "";
804:             setSearchState(SEARCH_IDLE);
805:         }
806:         emit("blankSearchQueryIgnored",
807:                 "keptQuery", searchQuery,
808:                 "keptProposals", proposals.size(),
809:                 "cancelledPendingDispatch", cancelledPending);
810:         notifyObservers();
811:     }
