813:     private void enterRemoteQuery(JSONObject payload) {
814:         registerResponseDeadlines(payload);
815:         Long at = timestampOf(payload);
816:         if (at != null) {
817:             useControlledClock(at);
818:             advanceControlledClockTo(at);
819:         }
820:         String raw = firstNonBlank(Text.optString(payload, "query"), Text.optString(payload, "searchQuery"));
821:         if (!searchScreenOpen()) {
822:             openSearch(Json.object());
823:         }
824:         onSearchQueryChanged(raw, at);
825:     }
