827:     /** Moves a controlled clock forward, running everything that becomes due on the way. */
828:     public void advanceControlledClockTo(long targetMillis) {
829:         DomainScheduler active = scheduler;
830:         if (active instanceof ControlledDomainScheduler) {
831:             ((ControlledDomainScheduler) active).advanceTo(targetMillis);
832:         }
833:     }
834: 
835:     private void advanceClock(JSONObject payload) {
836:         registerResponseDeadlines(payload);
837:         JSONArray completions = payload.optJSONArray("completions");
838:         if (completions != null) {
839:             for (int index = 0; index < completions.length(); index++) {
840:                 JSONObject entry = completions.optJSONObject(index);
841:                 if (entry != null) {
842:                     JSONObject completion = entry.optJSONObject("completion");
843:                     registerResponseDeadline(Text.optString(entry, "query"),
844:                             completion == null ? entry : completion);
845:                 }
846:             }
847:         }
848:         Long to = timestampOf(payload);
849:         if (to == null) {
850:             settlePendingWork();
851:             notifyObservers();
852:             return;
853:         }
854:         useControlledClock(to);
855:         emit("clockAdvanced", "toMs", to);
856:         advanceControlledClockTo(to);
857:         notifyObservers();
858:     }
859: 
860:     /**
861:      * Runs every piece of page work that is already scheduled: a pending debounce and the responses
862:      * that land after it. Used by the wait steps of a driver, and when a clock is advanced without
863:      * a target time.
864:      */
865:     private void settlePendingWork() {
866:         if (!(scheduler instanceof ControlledDomainScheduler)) {
867:             return;
868:         }
869:         ControlledDomainScheduler clock = (ControlledDomainScheduler) scheduler;
870:         for (int round = 0; round < 16 && clock.hasPendingTasks(); round++) {
871:             long due = clock.nextDueAt();
872:             if (due < 0L) {
873:                 return;
874:             }
875:             clock.advanceTo(due);
876:         }
877:     }
878: 
879:     private void waitFor(String expectation) {
880:         settlePendingWork();
881:         trace.add("DomainPageOwner.await(" + expectation + ")");
882:         notifyObservers();
883:     }
