885:     private void dispatchSearch(final String normalizedQuery) {
886:         pendingDispatch = null;
887:         if (!normalizedQuery.equals(searchQuery)) {
888:             emit("searchDispatchSkipped",
889:                     "query", normalizedQuery,
890:                     "latestQuery", searchQuery,
891:                     "reason", "superseded before dispatch");
892:             return;
893:         }
894:         final Backend currentBackend = backend;
895:         if (currentBackend == null) {
896:             applySearchError(normalizedQuery, "no domain backend is available");
897:             return;
898:         }
899:         final int generation = queryGeneration;
900:         searchRequestCount++;
901:         latestDispatchedQuery = normalizedQuery;
902:         dispatchedQueries.add(normalizedQuery);
903:         trim(dispatchedQueries);
904:         searchError = "";
905:         setSearchState(SEARCH_LOADING);
906:         emit("searchForDomains",
907:                 "query", normalizedQuery,
908:                 "normalizedQuery", normalizedQuery,
909:                 "requestIndex", searchRequestCount,
910:                 "generation", generation);
911:         trace.add("DomainPageOwner.searchForDomains(" + normalizedQuery + ")");
912:         notifyObservers();
913:         scheduler.executeOnWorker(new Runnable() {
914:             @Override public void run() {
915:                 JSONObject response;
916:                 try {
917:                     response = currentBackend.searchDomainSuggestions(normalizedQuery);
918:                 } catch (Exception error) {
919:                     response = errorResponse(error);
920:                 }
921:                 final JSONObject payload = response == null
922:                         ? errorResponse(new IllegalStateException("the suggestions response was empty"))
923:                         : response;
924:                 scheduler.post(new Runnable() {
925:                     @Override public void run() {
926:                         deliverSearchResponse(generation, normalizedQuery, payload);
927:                     }
928:                 });
929:             }
930:         });
931:     }
932: 
933:     /**
934:      * Delivers a suggestions response. A response that the network still owes at a later moment is
935:      * held until its due time, so an older response really can land after a newer query.
936:      */
937:     private void deliverSearchResponse(int generation, String query, JSONObject response) {
938:         long dueAt = responseDueAt(query);
939:         if (dueAt > scheduler.nowMillis()) {
940:             final int requestGeneration = generation;
941:             final String requestQuery = query;
942:             final JSONObject requestResponse = response;
943:             scheduler.postDelayed(new Runnable() {
944:                 @Override public void run() {
945:                     applySearchResponse(requestGeneration, requestQuery, requestResponse);
946:                 }
947:             }, dueAt - scheduler.nowMillis());
948:             return;
949:         }
950:         applySearchResponse(generation, query, response);
951:     }
952: 
953:     private void applySearchResponse(int generation, String query, JSONObject response) {
954:         if (generation != queryGeneration || !query.equals(searchQuery)) {
955:             emit("staleSearchCompletionIgnored",
956:                     "query", query,
957:                     "latestQuery", searchQuery,
958:                     "generation", generation,
959:                     "latestGeneration", queryGeneration);
960:             return;
961:         }
962:         if (isErrorResponse(response)) {
963:             applySearchError(query, Text.isBlank(errorMessage(response))
964:                     ? "the domain suggestions could not be loaded" : errorMessage(response));
965:             return;
966:         }
967:         String remoteQuery = Text.normalizeQuery(Text.first(response, new String[] { "query", "search", "searchedQuery" }));
968:         if (!remoteQuery.isEmpty() && !remoteQuery.equals(query)) {
969:             applySearchError(query, "the domain suggestions answered the query \"" + remoteQuery + "\"");
970:             return;
971:         }
972:         // The proposals always come from the response; nothing else may claim them.
973:         JSONArray suggestions = suggestionsOf(response);
974:         List<DomainSuggestion> paid = DomainSuggestion.paidProposals(suggestions);
975:         proposals.clear();
976:         proposals.addAll(paid);
977:         searchError = "";
978:         setSearchState(SEARCH_POPULATED);
979:         emit("searchResults",
980:                 "query", query,
981:                 "proposals", proposals.size(),
982:                 "excludedFreeSuggestions", countFreeSuggestions(suggestions));
983:         notifyObservers();
984:     }
985: 
986:     private void applySearchError(String query, String message) {
987:         searchError = Text.orEmpty(message);
988:         proposals.clear();
989:         setSearchState(SEARCH_ERROR);
990:         emit("searchFailed", "query", query, "message", searchError, "retryable", true);
991:         notifyObservers();
992:     }
