994:     /** Retries a failed suggestions request with the retained query. */
995:     public void retrySearch() {
996:         trace.add("DomainPageOwner.retrySearch()");
997:         String query = searchQuery.isEmpty() ? latestDispatchedQuery : searchQuery;
998:         if (query.isEmpty()) {
999:             emit("searchRetryIgnored", "reason", "no retained query");
1000:             return;
1001:         }
1002:         searchQuery = query;
1003:         queryGeneration++;
1004:         cancelPendingDispatch();
1005:         emit("retryDomainSearch", "query", query);
1006:         dispatchSearch(query);
1007:     }
