1009:     /**
1010:      * Applies a suggestions payload that arrived outside the debounced search, for example a
1011:      * suggestions response that was already in flight when the search screen opened.
1012:      */
1013:     private void applySearchResultsPayload(JSONObject payload) {
1014:         if (payload == null) {
1015:             return;
1016:         }
1017:         String query = Text.normalizeQuery(firstNonBlank(Text.optString(payload, "query"), searchQuery));
1018:         if (query.isEmpty()) {
1019:             emit("searchResultsIgnored", "reason", "the payload names no query");
1020:             return;
1021:         }
1022:         // A delivered response owns the visible results, so any pending debounce is dropped and the
1023:         // proposals go through the very same path a network response takes.
1024:         cancelPendingDispatch();
1025:         searchQuery = query;
1026:         applySearchResponse(queryGeneration, query, payload);
1027:     }
