1048:     /**
1049:      * The proposal a screen action refers to. A search result tap only carries the tapped domain,
1050:      * so the proposal is read back from the visible results to keep its product, price and privacy
1051:      * fields; a proposal handed over as a whole object is used as it is.
1052:      */
1053:     private DomainSuggestion proposalFrom(JSONObject payload) {
1054:         JSONObject proposalJson = payload.optJSONObject("proposal");
1055:         if (proposalJson == null) {
1056:             proposalJson = payload.optJSONObject("selectedProposal");
1057:         }
1058:         if (proposalJson != null) {
1059:             return DomainSuggestion.fromJson(proposalJson, 0d);
1060:         }
1061:         String domain = Text.optString(payload, "domain");
1062:         if (!Text.isBlank(domain)) {
1063:             DomainSuggestion visible = DomainSuggestion.findByDomain(proposals, domain);
1064:             if (visible != null) {
1065:                 return visible;
1066:             }
1067:             if (selectedProposal != null && selectedProposal.domain.equalsIgnoreCase(domain)) {
1068:                 return selectedProposal;
1069:             }
1070:             return null;
1071:         }
1072:         return selectedProposal;
1073:     }
