1123:         String site = MODE_EXISTING_SITE.equals(mode)
1124:                 ? firstNonBlank(siteFrom(payload), existingSite) : "";
1125:         boolean sameChoice = mode.equals(purchaseMode)
1126:                 && (!MODE_EXISTING_SITE.equals(mode) || site.equalsIgnoreCase(existingSite));
1127:         if (sameChoice && cartState != CART_IDLE) {
1128:             // The same purchase is in flight or already submitted; no duplicate cart is created.
1129:             emit("duplicateCartSubmissionIgnored",
1130:                     "mode", purchaseMode,
1131:                     "domain", selectedProposal.domain,
1132:                     "cartState", cartState);
1133:             return;
1134:         }
1135:         purchaseMode = mode;
1136:         existingSite = site;
1137:         resetCart();
1138:         purchaseScreenOpen = true;
1139:         screen = SCREEN_DOMAIN_PURCHASE;
1140:         if (MODE_EXISTING_SITE.equals(mode) && Text.isBlank(existingSite)) {
1141:             // An existing-site cart without a target site cannot be submitted yet.
1142:             cartProgress = "waitingForSite:" + mode;
1143:             recordCartProgress();
1144:             emit("existingSiteRequired", "domain", selectedProposal.domain, "mode", mode);
1145:             notifyObservers();
