1164:     /** Submits the cart for the selected mode; at most one request per explicit attempt. */
1165:     public void submitCart() {
1166:         if (selectedProposal == null) {
1167:             emit("cartSubmissionIgnored", "reason", "no proposal was selected");
1168:             return;
1169:         }
1170:         if (Text.isBlank(purchaseMode)) {
1171:             emit("cartSubmissionIgnored", "reason", "no purchase mode was chosen",
1172:                     "domain", selectedProposal.domain);
1173:             return;
1174:         }
1175:         if (registeredAttempt == purchaseAttempt) {
1176:             // This exact purchase already went through checkout, so no second cart is created for
1177:             // it; selecting another domain starts a new attempt.
1178:             emit("cartSubmissionIgnored", "reason", "the checkout already completed",
1179:                     "domain", selectedProposal.domain,
1180:                     "purchaseAttempt", purchaseAttempt);
1181:             return;
1182:         }
1183:         if (cartState == CART_SUBMITTING) {
1184:             emit("duplicateCartSubmissionIgnored", "mode", purchaseMode, "domain", selectedProposal.domain);
1185:             return;
1186:         }
1187:         if (cartState == CART_ERROR) {
1188:             // The failure has to be acknowledged first, which keeps the proposal selected.
1189:             emit("cartSubmissionIgnored", "reason", "the cart error has to be acknowledged first",
1190:                     "mode", purchaseMode, "domain", selectedProposal.domain);
1191:             return;
1192:         }
1193:         if (cartState == CART_COMPLETED) {
1194:             emit("duplicateCartSubmissionIgnored", "mode", purchaseMode, "domain", selectedProposal.domain);
1195:             return;
1196:         }
1197:         final Backend currentBackend = backend;
1198:         if (currentBackend == null) {
1199:             applyCartError(purchaseMode, selectedProposal.domain, "no domain backend is available");
1200:             return;
1201:         }
1202:         final int requestId = ++cartRequestCount;
1203:         final String mode = purchaseMode;
1204:         final String domain = selectedProposal.domain;
1205:         final JSONObject request = cartRequest(mode, domain);
1206:         cartState = CART_SUBMITTING;
1207:         cartProgress = "submitting:" + mode;
1208:         recordCartProgress();
1209:         cartError = "";
1210:         emit("cartSubmitted", "mode", mode, "domain", domain, "requestIndex", requestId,
1211:                 "purchaseAttempt", purchaseAttempt,
1212:                 "productId", selectedProposal.productId, "supportsPrivacy", selectedProposal.supportsPrivacy,
1213:                 "progress", cartProgress);
1214:         trace.add("DomainPageOwner.createCart(" + mode + ")");
1215:         notifyObservers();
1216:         scheduler.executeOnWorker(new Runnable() {
1217:             @Override public void run() {
1218:                 JSONObject response;
1219:                 try {
1220:                     response = currentBackend.createCartForProposal(request);
1221:                 } catch (Exception error) {
1222:                     response = errorResponse(error);
1223:                 }
1224:                 final JSONObject payload = response == null
1225:                         ? errorResponse(new IllegalStateException("the cart could not be created")) : response;
1226:                 scheduler.post(new Runnable() {
1227:                     @Override public void run() {
1228:                         applyCartResponse(requestId, mode, domain, payload);
1229:                     }
1230:                 });
1231:             }
1232:         });
1233:     }
